// The design system on its easel: the product's tokens — injected as a
// file, or generated by an AI from a moodboard and a logo — validated on
// a sheet and retouched by hand; the kit's catalogue — the harness's bases
// ticked, custom components prompted (a text, a reference image, a sketch)
// — generated several at once; and the canvas, every component rendered
// alone on a card, edited by request pins an AI applies to the fragment
// (a draft, saved as a fork or a replacement, never on the roadmap), with
// who uses it on which branch. Everything lives on the product's
// `design-system` branch, read and written through `/api/design` and
// `/api/kit`, published from the bar.
(() => {
  'use strict';

  const BOARD = 'kit--components';
  const SLUG = 'design-system';
  const CARD_W = 420;
  const CARD_GAP = 28;
  const CARD_MIN = 140;
  const CARD_MAX = 640;
  const WIDTH = 1320;
  const MIN_HEIGHT = 480;
  const POLL_MS = 4000;
  const BUSY_MS = 1500;
  const TAB = 'harness.kit.tab';

  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const kept = (key, fallback) => { try { const v = localStorage.getItem(key); return v == null ? fallback : JSON.parse(v); } catch (e) { return fallback; } };
  const keep = (key, value) => { try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) { /* a preference */ } };
  const post = (url, body) => fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body || {}) });
  const call = (url, body) => post(url, body).then(said);
  const said = async (res) => { const text = await res.text(); if (!res.ok) throw new Error(text || res.statusText); try { return JSON.parse(text); } catch (e) { return text; } };
  const stateName = { pending: 'to generate', running: 'generating…', generated: 'generated', failed: 'failed' };

  function mount(host, opts) {
    host.innerHTML = '<div class="dm kt">'
      + '<div class="dm-bar">'
      + '<div class="mk-views" role="group" aria-label="view"><button type="button" data-kt="tab" data-tab="system">design system</button><button type="button" data-kt="tab" data-tab="catalogue">catalogue</button><button type="button" data-kt="tab" data-tab="canvas">canvas</button></div>'
      + '<span class="dm-origin kt-origin">reading the design system…</span>'
      + '<span class="spacer"></span>'
      + '<span class="kt-state"></span>'
      + '<input class="kt-message" maxlength="200" placeholder="what changed, in a line" hidden aria-label="commit message">'
      + '<button type="button" class="mini" data-kt="publish" hidden title="Commit the workspace on the design-system branch and push it">publish the design</button>'
      + '<button type="button" class="mini" data-kt="discard" hidden title="Drop the workspace: the branch as committed again">discard</button>'
      + '</div>'
      + '<div class="kt-body"><div class="kt-pane kt-system" hidden></div><div class="kt-pane kt-catalogue" hidden></div><div class="dm-main kt-canvas" hidden><div class="dm-board kt-board"></div></div></div>'
      + '<div class="mk-toast" hidden></div>'
      + '</div>';
    const q = (s) => host.querySelector(s);
    const st = { tab: (opts && opts.tab) || kept(TAB, 'system') || 'system', reply: null, usages: null, board: null, cards: [], stamp: '', timer: null, gone: false, sketch: null, busy: false, pinned: false, rev: {}, applying: {}, custom: (opts && opts.custom) || null, editTimer: null, lastDrawn: '' };

    // ---- reading -------------------------------------------------------------------------------
    async function load(quiet) {
      try {
        const res = await fetch('/api/design');
        if (!res.ok) throw new Error(await res.text());
        const reply = await res.json();
        if (st.gone) return;
        const changed = reply.stamp !== st.stamp;
        st.reply = reply;
        st.stamp = reply.stamp;
        drawBar();
        if (!quiet || changed || running().length) draw(changed);
      } catch (e) {
        if (!st.gone) say('the design system could not be read: ' + esc(String(e.message || e).split('\n')[0]));
      }
      clearTimeout(st.timer);
      st.timer = setTimeout(() => load(true), running().length ? BUSY_MS : POLL_MS);
    }
    const running = () => ((st.reply && st.reply.jobs) || []).filter((j) => j.state === 'queued' || j.state === 'running');
    const design = () => (st.reply && st.reply.design) || { design: {}, tokens: [], candidate: [], tokens_css: '', missing: [] };
    const catalog = () => (st.reply && st.reply.catalog) || [];
    const entry = (name) => catalog().find((e) => e.name === name) || null;
    function say(html) { q('.kt-origin').innerHTML = html; }
    function toast(html, ms) {
      const t = q('.mk-toast');
      t.innerHTML = html; t.hidden = false;
      clearTimeout(st.toastTimer);
      st.toastTimer = setTimeout(() => { t.hidden = true; }, ms || 6000);
    }
    async function act(label, work, after) {
      if (st.busy) return;
      st.busy = true;
      say(`<span class="spin"></span> ${esc(label)}…`);
      try {
        const got = await work();
        say('');
        if (after) after(got);
        await load(false);
      } catch (e) {
        say(`<span class="bad">${esc(String(e.message || e).split('\n')[0])}</span>`);
      }
      st.busy = false;
    }

    // ---- the bar -------------------------------------------------------------------------------
    function drawBar() {
      host.querySelectorAll('[data-kt="tab"]').forEach((b) => b.classList.toggle('on', b.dataset.tab === st.tab));
      const r = st.reply;
      if (!r) return;
      const d = r.design.design || {};
      const state = d.state === 'validated' ? `<span class="tag ok">validated${d.candidate ? ' · a candidate waits' : ''}</span>` : d.state === 'candidate' ? '<span class="tag warn">candidate — validate it</span>' : '<span class="tag">no design system yet</span>';
      const n = catalog().filter((e) => e.state === 'generated').length;
      q('.kt-state').innerHTML = `${state} <span class="muted">· ${n} component${n === 1 ? '' : 's'} in the kit${r.edited ? ' · <b class="warn">edited, not published</b>' : ''}${r.no_claude ? ' · <span class="bad">no Claude: nothing generates</span>' : ''}</span>`;
      q('.kt-message').hidden = !r.edited;
      q('[data-kt="publish"]').hidden = !r.edited;
      q('[data-kt="discard"]').hidden = !r.edited;
      if (!q('.kt-origin').innerHTML.includes('spin')) say(`branch <b>${SLUG}</b> · ${esc(r.model)} · ${r.sessions} session${r.sessions === 1 ? '' : 's'} at once`);
    }
    function setTab(tab) {
      st.tab = tab; keep(TAB, tab);
      draw(true);
    }
    function draw(changed) {
      drawBar();
      q('.kt-system').hidden = st.tab !== 'system';
      q('.kt-catalogue').hidden = st.tab !== 'catalogue';
      q('.kt-canvas').hidden = st.tab !== 'canvas';
      if (st.tab === 'system') drawSystem();
      else if (st.tab === 'catalogue') drawCatalogue();
      else drawCanvas(changed);
    }

    // ---- the design system: inject, generate, validate, retouch ---------------------------------
    function sheet(css, tokens) {
      const t = (path) => (tokens.find((x) => x.path === path) || {}).value || '';
      const colours = tokens.filter((x) => x.kind === 'color' || /^color\./.test(x.path));
      const swatches = colours.map((c) => `<div class="sw"><i style="background:var(--${c.path.replace(/\./g, '-')})"></i><b>${esc(c.path.replace(/^color\./, ''))}</b><small>${esc(c.value)}</small></div>`).join('');
      const spaces = tokens.filter((x) => /^space\./.test(x.path)).map((s) => `<div class="sp"><i style="width:var(--${s.path.replace(/\./g, '-')})"></i><small>${esc(s.path.replace(/^space\./, ''))} · ${esc(s.value)}</small></div>`).join('');
      const radii = tokens.filter((x) => /^radius\./.test(x.path)).map((r) => `<div class="rd"><i style="border-radius:var(--${r.path.replace(/\./g, '-')})"></i><small>${esc(r.path.replace(/^radius\./, ''))}</small></div>`).join('');
      return `<!doctype html><html><head><meta charset="utf-8"><style>${css}
body{margin:0;padding:18px;font-family:var(--font-family,system-ui,sans-serif);color:var(--color-text,#111);background:var(--color-surface,#fff);font-size:var(--font-size-base,15px)}
h1{font-family:var(--font-family-heading,system-ui);font-size:var(--font-size-heading,28px);font-weight:var(--font-weight-heading,700);margin:0 0 4px}
h2{font-size:var(--font-size-small,12px);text-transform:uppercase;letter-spacing:.08em;color:var(--color-text-muted,#666);margin:22px 0 8px}
p{margin:0;color:var(--color-text-muted,#666)}
.row{display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end}
.sw{width:92px}.sw i{display:block;height:48px;border-radius:var(--radius-medium,8px);border:1px solid var(--color-border,#ddd)}.sw b{display:block;font-size:11px;margin-top:4px}.sw small{font-size:10px;color:var(--color-text-muted,#666)}
.sp i{display:block;height:10px;background:var(--color-primary,#2b6cb0);border-radius:2px}.sp small{font-size:10px;color:var(--color-text-muted,#666)}
.rd i{display:block;width:48px;height:48px;background:var(--color-surface-2,#eee);border:1px solid var(--color-border,#ddd)}.rd small{font-size:10px;color:var(--color-text-muted,#666)}
.samples{display:flex;flex-wrap:wrap;gap:16px;align-items:flex-start}
button{font:inherit;padding:var(--space-2,8px) var(--space-3,16px);border-radius:var(--radius-medium,8px);border:1px solid var(--color-primary,#2b6cb0);background:var(--color-primary,#2b6cb0);color:var(--color-primary-contrast,#fff);cursor:pointer}
button.secondary{background:transparent;color:var(--color-primary,#2b6cb0)}
input{font:inherit;padding:var(--space-2,8px) var(--space-3,16px);border:var(--border-width,1px) solid var(--color-border,#ddd);border-radius:var(--radius-medium,8px);background:var(--color-surface,#fff);color:inherit}
.card{width:240px;background:var(--color-surface,#fff);border:var(--border-width,1px) solid var(--color-border,#ddd);border-radius:var(--radius-large,16px);box-shadow:var(--shadow-high,0 8px 24px rgba(0,0,0,.18));padding:var(--space-3,16px)}
.card h3{margin:0 0 6px;font-family:var(--font-family-heading,system-ui);font-size:var(--font-size-large,20px)}
.badge{display:inline-block;font-size:var(--font-size-small,12px);padding:var(--space-1,4px) var(--space-2,8px);border-radius:var(--radius-pill,999px);background:var(--color-accent,#d97706);color:var(--color-primary-contrast,#fff)}
</style></head><body>
<h1>Heading in the heading face</h1><p>Body text in the body face, ${esc(t('font.family').split(',')[0] || 'the system font')}, at ${esc(t('font.size-base'))}.</p>
<h2>Palette</h2><div class="row">${swatches}</div>
<h2>Spacing</h2><div class="row">${spaces}</div>
<h2>Radii</h2><div class="row">${radii}</div>
<h2>Samples</h2><div class="samples"><button type="button">Primary</button><button type="button" class="secondary">Secondary</button><input value="A text field"><span class="badge">New</span><div class="card"><h3>A card</h3><p>Surface, border, radius and shadow together.</p></div></div>
</body></html>`;
    }
    function tokensTable(tokens, id) {
      return `<table class="kt-tokens" data-tokens="${id}"><tbody>${tokens.map((t) => {
        const colour = t.kind === 'color' || (/^color\./.test(t.path) && /^#[0-9a-f]{3,8}$/i.test(t.value));
        return `<tr><td class="mono">${esc(t.path)}</td><td>${colour && /^#[0-9a-f]{6}$/i.test(t.value) ? `<input type="color" data-token="${esc(t.path)}" value="${esc(t.value)}">` : ''}<input type="text" class="kt-token" data-token="${esc(t.path)}" value="${esc(t.value)}" maxlength="300"></td></tr>`;
      }).join('')}</tbody></table>`;
    }
    function drawSystem() {
      const pane = q('.kt-system');
      const r = st.reply;
      if (!r) { pane.innerHTML = '<div class="muted">reading…</div>'; return; }
      const dv = r.design; const d = dv.design || {};
      const none = d.state === 'none' || !dv.tokens.length;
      const mood = (d.moodboard || []).map((m) => `<figure class="kt-thumb"><img src="/mock/${SLUG}/design/${esc(m)}?v=${esc(r.stamp)}" alt="${esc(m)}"><button type="button" class="mini" data-kt="remove-asset" data-kind="moodboard" data-name="${esc(m)}" title="remove">×</button></figure>`).join('');
      const logo = d.logo ? `<figure class="kt-thumb kt-logo"><img src="/mock/${SLUG}/design/${esc(d.logo)}?v=${esc(r.stamp)}" alt="logo"><button type="button" class="mini" data-kt="remove-asset" data-kind="logo" data-name="${esc(d.logo)}" title="remove">×</button></figure>` : '<span class="muted">no logo</span>';
      const key = JSON.stringify([d, dv.tokens_json, dv.candidate_json, r.stamp, r.no_claude]);
      if (key === st.lastDrawn && pane.innerHTML) return;
      st.lastDrawn = key;
      const sources = `<div class="kt-cols">
        <section class="kt-block">
          <h3>Inject a design system</h3>
          <p class="muted">A tokens file in the W3C design tokens format (colours, fonts, spacings, radii, shadows); what it leaves out of the kit's vocabulary is filled with neutral values. A Figma variables export comes later.</p>
          <div class="kt-row"><input type="file" accept=".json,application/json" data-kt="tokens-file"><button type="button" class="mini" data-kt="tokens-example" title="Fill the box with the harness's neutral tokens, to edit">example</button></div>
          <textarea class="kt-json" rows="6" placeholder='{"color": {"primary": {"$type": "color", "$value": "#2b6cb0"}}, …}'></textarea>
          <div class="kt-row"><button type="button" class="mini on" data-kt="inject">inject these tokens</button><span class="kt-hint muted">${d.state === 'validated' ? 'they wait as a candidate beside the validated ones' : 'they become the candidate, to validate'}</span></div>
        </section>
        <section class="kt-block">
          <h3>Or generate one</h3>
          <p class="muted">From a moodboard, the company's logo and a brief: one AI session reads the images and draws the tokens. Change the moodboard and generate again when it is not right.</p>
          <div class="kt-row"><b>moodboard</b><input type="file" accept="image/*" multiple data-kt="mood-files"></div>
          <div class="kt-thumbs">${mood || '<span class="muted">no image yet</span>'}</div>
          <div class="kt-row"><b>logo</b><input type="file" accept="image/*" data-kt="logo-file">${logo}</div>
          <textarea class="kt-brief" rows="3" maxlength="4000" placeholder="the brand, the mood, who it speaks to — a few lines">${esc(d.brief || '')}</textarea>
          <div class="kt-row"><button type="button" class="mini on" data-kt="generate" ${r.no_claude ? 'disabled' : ''}>${d.source === 'generated' ? 'generate again' : 'generate'}</button><span class="kt-hint muted">${r.no_claude ? 'no Claude at hand' : 'one question, a minute or two'}</span></div>
        </section>
      </div>`;
      const open = new Set([...pane.querySelectorAll('details[data-keep]')].filter((x) => x.open).map((x) => x.dataset.keep));
      pane.innerHTML = `${none ? sources : ''}
      ${none ? '<div class="callout">No design system yet: inject a tokens file, or generate one from a moodboard. The kit is generated from it once it is validated.</div>' : ''}
      ${d.candidate && dv.candidate.length ? `<section class="kt-block kt-candidate"><h3>The candidate <span class="tag warn">waiting</span></h3><p class="muted">Generated or injected after the validation: the validated tokens stay until you take this one.</p><iframe class="kt-sheet" title="the candidate" srcdoc="${esc(sheet(cssOf(dv.candidate), dv.candidate))}"></iframe><div class="kt-row"><button type="button" class="mini on" data-kt="validate">validate the candidate</button><button type="button" class="mini" data-kt="drop-candidate">drop it</button></div></section>` : ''}
      ${!none ? `<section class="kt-block"><h3>The sheet ${d.state === 'validated' ? '<span class="tag ok">validated</span>' : '<span class="tag warn">candidate</span>'}</h3>
        <iframe class="kt-sheet" title="the design system" srcdoc="${esc(sheet(dv.tokens_css, dv.tokens))}"></iframe>
        <div class="kt-row">${d.state !== 'validated' ? '<button type="button" class="mini on" data-kt="validate" title="Validate: the kit may be generated, and a roadmap task installs the design system in the product">validate</button>' : ''}${d.issue ? `<a class="tag-link" href="${esc(d.issue)}" target="_blank" rel="noopener">the roadmap task that installs it ↗</a>` : ''}${d.validatedAt ? `<span class="muted">validated ${esc(String(d.validatedAt).slice(0, 16).replace('T', ' '))}</span>` : ''}${dv.missing.length ? `<span class="muted">${dv.missing.length} token(s) at the neutral value</span>` : ''}</div>
        <details class="kt-edit" data-keep="edit"><summary>retouch the tokens by hand</summary><p class="muted">A change is kept as you type; the sheet and every component follow, through the variables.</p>${tokensTable(dv.tokens, 'tokens')}</details>
      </section>
      <section class="kt-block"><h3>The simulated page</h3>
        <p class="muted">A contact page the harness draws with the kit's components only: every one the canvas saves shows here too. One not generated yet shows as a dashed box.</p>
        <iframe class="kt-showcase" title="the simulated page" src="/mock/${SLUG}/__showcase/contact?v=${esc(r.stamp)}"></iframe>
      </section>
      <details class="kt-block kt-regen" data-keep="regen"><summary>regenerate the design system</summary>${sources}</details>` : ''}`;
      pane.querySelectorAll('details[data-keep]').forEach((x) => { if (open.has(x.dataset.keep)) x.open = true; });
      if (st.custom) { setTab('catalogue'); }
    }
    const cssOf = (tokens) => ':root{' + tokens.map((t) => `--${t.path.replace(/\./g, '-')}:${t.value};`).join('') + '}';
    function tokensJsonEdited() {
      // The table's values folded back into the tokens file: a W3C group per path.
      const root = {};
      host.querySelectorAll('.kt-token').forEach((input) => {
        const parts = input.dataset.token.split('.');
        let at = root;
        parts.forEach((p, i) => {
          if (i === parts.length - 1) at[p] = { $value: input.value };
          else { at[p] = at[p] || {}; at = at[p]; }
        });
      });
      return JSON.stringify(root, null, 2);
    }
    async function upload(kind, file, component) {
      const res = await fetch(`/api/design/asset?kind=${kind}&name=${encodeURIComponent(file.name || 'sketch.png')}${component ? '&component=' + encodeURIComponent(component) : ''}`, { method: 'POST', body: file });
      return said(res);
    }

    // ---- the catalogue: the bases ticked, the customs prompted, the generation ------------------
    function drawCatalogue() {
      const pane = q('.kt-catalogue');
      const r = st.reply;
      if (!r) { pane.innerHTML = '<div class="muted">reading…</div>'; return; }
      const list = catalog();
      const validated = (r.design.design || {}).state === 'validated';
      const jobs = r.jobs || [];
      const jobOf = (name) => jobs.find((j) => j.name === name);
      const row = (e) => {
        const job = jobOf(e.name);
        const state = job && (job.state === 'queued' || job.state === 'running') ? `<span class="tag acc"><span class="spin"></span> ${job.state}</span>` : e.state === 'generated' ? `<span class="tag ok">${e.checks.length ? 'generated · fails the check' : 'generated'}</span>` : e.state === 'failed' ? `<span class="tag bad" title="${esc(e.why)}">failed</span>` : e.checked ? '<span class="tag">to generate</span>' : '';
        return `<li class="kt-item${e.checked ? '' : ' off'}" data-item="${esc(e.name)}">
          ${!e.base ? '<span class="kt-check kt-custom-mark" title="custom">✎</span>' : `<input type="checkbox" class="kt-check" data-base="${esc(e.base)}" ${e.checked ? 'checked' : ''} ${e.state === 'generated' ? 'disabled title="generated: remove it from the canvas"' : ''}>`}
          <b class="mono">${esc(e.name)}</b><span class="kt-title">${esc(e.title)}</span>
          <span class="kt-what muted">${esc(e.what || e.prompt)}</span>
          ${state}${e.why && e.state === 'failed' ? `<span class="kt-why muted">${esc(e.why)}</span>` : ''}
          ${e.recoded ? `<span class="tag warn" title="${esc(e.recoded)}">recoded</span>` : ''}
          ${e.reference ? `<img class="kt-ref" src="/mock/${SLUG}/kit/${esc(e.reference)}?v=${esc(r.stamp)}" alt="reference">` : ''}
          <span class="kt-item-actions">${e.checked && validated && !(job && job.state === 'running') ? `<button type="button" class="mini" data-kt="generate-one" data-name="${esc(e.name)}">${e.state === 'generated' ? 'generate again' : 'generate'}</button>` : ''}${!e.base ? `<button type="button" class="mini" data-kt="edit-prompt" data-name="${esc(e.name)}">prompt</button><button type="button" class="mini" data-kt="reference" data-name="${esc(e.name)}">reference…</button>` : ''}${!e.base && e.state !== 'generated' ? `<button type="button" class="mini" data-kt="delete" data-name="${esc(e.name)}">remove</button>` : ''}</span>
        </li>`;
      };
      const bases = list.filter((e) => !!e.base);
      const customs = list.filter((e) => !e.base);
      const pending = list.filter((e) => e.checked && (e.state === 'pending' || e.state === 'failed')).length;
      const done = jobs.filter((j) => j.state === 'done').length;
      const failed = jobs.filter((j) => j.state === 'failed');
      pane.innerHTML = `${validated ? '' : '<div class="callout">The kit is styled from the design system: validate it first (the <b>design system</b> tab), then tick and generate.</div>'}
        <div class="kt-cols">
          <section class="kt-block kt-bases"><h3>Standard components <small class="muted">tick what the application needs</small></h3><ul class="kt-list">${bases.map(row).join('')}</ul></section>
          <section class="kt-block kt-customs"><h3>Custom components <small class="muted">prompted, drawn without a base</small></h3>
            <ul class="kt-list">${customs.map(row).join('') || '<li class="muted">none yet</li>'}</ul>
            <form class="kt-custom" autocomplete="off">
              <div class="kt-row"><input name="name" maxlength="60" placeholder="Name, like HeroBanner" value="${esc(st.custom && st.custom.name || '')}" aria-label="name"><input name="title" maxlength="80" placeholder="title, for humans" aria-label="title"></div>
              <textarea name="prompt" rows="3" maxlength="4000" placeholder="what it shows and does, visually — the AI draws it from these words">${esc(st.custom && st.custom.prompt || '')}</textarea>
              <div class="kt-row"><label class="muted">reference image <input type="file" name="reference" accept="image/*"></label><button type="button" class="mini" data-kt="sketch-toggle">draw a sketch</button></div>
              <div class="kt-sketch" hidden><canvas width="420" height="240"></canvas><div class="kt-row"><button type="button" class="mini" data-kt="sketch-clear">clear</button><span class="muted">draw with the pointer: a rough layout is enough</span></div></div>
              <div class="kt-row"><button type="submit" class="mini on">add the component</button><span class="kt-form-state muted"></span></div>
            </form>
          </section>
        </div>
        <section class="kt-block kt-forge"><h3>Generation <small class="muted">${r.sessions} session${r.sessions === 1 ? '' : 's'} at once on ${esc(r.model)}: each component is one question, the base restyled with the tokens</small></h3>
          <div class="kt-row"><button type="button" class="mini on" data-kt="generate-all" ${validated && pending && !r.no_claude ? '' : 'disabled'}>generate ${pending ? pending + ' component' + (pending === 1 ? '' : 's') : 'the kit'}</button>
          ${running().length ? `<span class="tag acc"><span class="spin"></span> ${running().length} left · ${done} done</span>` : jobs.length ? `<span class="muted">${done} done${failed.length ? `, ${failed.length} failed — generate again takes only those` : ''}</span>` : '<span class="muted">what is generated stays; a run stopped halfway resumes where it was</span>'}</div>
          ${jobs.length ? `<ul class="kt-jobs">${jobs.map((j) => `<li class="${esc(j.state)}"><b class="mono">${esc(j.name)}</b> <span>${esc(j.state)}</span>${j.why ? ` <small class="muted">${esc(j.why)}</small>` : ''}</li>`).join('')}</ul>` : ''}
        </section>`;
      if (st.custom) { st.custom = null; const t = pane.querySelector('textarea[name="prompt"]'); if (t) t.focus(); }
    }
    // The sketch pad: strokes on a canvas, uploaded as the component's reference.
    function armSketch(canvas) {
      const ctx = canvas.getContext('2d');
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.strokeStyle = '#222'; ctx.lineWidth = 2.5; ctx.lineCap = 'round';
      let drawing = false; let drawn = false;
      const at = (e) => { const r = canvas.getBoundingClientRect(); return { x: (e.clientX - r.left) * canvas.width / r.width, y: (e.clientY - r.top) * canvas.height / r.height }; };
      canvas.onpointerdown = (e) => { drawing = true; drawn = true; const p = at(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); canvas.setPointerCapture(e.pointerId); };
      canvas.onpointermove = (e) => { if (!drawing) return; const p = at(e); ctx.lineTo(p.x, p.y); ctx.stroke(); };
      canvas.onpointerup = canvas.onpointercancel = () => { drawing = false; };
      st.sketch = { canvas, clear: () => { ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, canvas.width, canvas.height); drawn = false; }, drawn: () => drawn, blob: () => new Promise((done) => canvas.toBlob(done, 'image/png')) };
    }

    // ---- the canvas: every component on a card, pins on them ------------------------------------
    const previewSrc = (name, draft, version) => `/mock/${SLUG}/__kit/${encodeURIComponent(name)}?${draft ? 'draft=1&' : ''}v=${encodeURIComponent(version || st.stamp)}`;
    const describe = (target) => (target && target.startsWith('kit:') ? 'the component ' + target.slice(4) : target || 'the canvas');
    const context = (target) => {
      const name = target && target.startsWith('kit:') ? target.slice(4) : '';
      const e = name ? entry(name) : null;
      if (!e) return 'The kit of the design system: its components, on the design-system branch under mock/kit/.';
      return `The kit component ${e.name} (${e.title}): ${e.what || e.prompt}\nIts fragment: mock/kit/${e.name}.html on the design-system branch (the folder you are in). The tokens: mock/design/tokens.css. A kit component is a visual primitive: no data of its own, no network; colours, fonts, spacings, radii and shadows only through var(--…).${e.recoded ? '\nRecoded by the code stage: ' + e.recoded : ''}`;
    };
    // The board is made once and kept: its zoom, its pins and the pins being
    // applied survive every reload. A reload redraws the cards in place.
    function drawCanvas(changed) {
      if (!st.board) {
        const onSession = opts && opts.onSession
          ? (note, ctx) => opts.onSession({ board: BOARD, id: note.id, on: describe(note.target), kind: note.kind, context: ctx, branch: SLUG, page: '' })
          : null;
        st.board = window.HarnessBoard.create(q('.kt-board'), {
          id: BOARD,
          describe,
          context,
          onSession,
          kinds: ['note', 'request'],
          backlog: false,
          apply: (note) => applyRequests(note.target ? note.target.slice(4) : '', [note]),
          onApplying: () => drawCards(),
          onLoaded: () => { if (opts && opts.pin && !st.pinned && st.board && st.board.goTo(opts.pin)) st.pinned = true; drawCards(); },
          bounds: () => ({ x: 0, y: 0, w: Math.max(WIDTH, st.board ? parseFloat(st.board.content.style.width) || WIDTH : WIDTH), h: Math.max(MIN_HEIGHT, st.board ? parseFloat(st.board.content.style.height) || MIN_HEIGHT : MIN_HEIGHT) }),
        });
        st.fitted = false;
        loadUsages();
      } else if (changed) loadUsages();
      drawCards();
      st.board.refresh();
    }
    // A card's preview is reloaded only when what it shows changed: its
    // fragment written again, its draft made, rewritten or dropped.
    const versionOf = (e) => `${e.generated_at || ''}-${e.draft ? 'd' : ''}${st.rev[e.name] || 0}`;
    function cardHtml(e) {
      const used = (st.usages && st.usages[e.name]) || [];
      // The requests waiting: written, not applied, not being applied.
      const pending = st.board ? st.board.all().filter((n) => n.target === 'kit:' + e.name && n.kind === 'request' && (n.state || 'pending') !== 'simulated' && (n.text || '').trim() && !st.board.isApplying(n.id)).length : 0;
      const working = st.applying[e.name] || 0;
      return `<div class="mk-card kt-card" data-pin="kit:${esc(e.name)}" data-card="${esc(e.name)}" data-version="${esc(versionOf(e))}" style="width:${CARD_W}px;--mf:var(--pin-design)">
          <div class="mk-card-head"><b>${esc(e.name)}</b><span class="mk-card-sys">${esc(e.title)}</span><span class="mk-card-tags">${e.variant_of ? `<i title="forked from ${esc(e.variant_of)}">fork of ${esc(e.variant_of)}</i>` : ''}${e.draft ? '<i class="bad">draft</i>' : ''}${e.checks.length ? `<i class="bad" title="${esc(e.checks.join('\n'))}">fails the check</i>` : '<i class="ok" title="reusable as it is by the real code">passes the check</i>'}${e.recoded ? `<i class="bad" title="${esc(e.recoded)}">recoded</i>` : ''}</span></div>
          <div class="mk-card-desc">${esc(e.what || e.prompt)}</div>
          <div class="mk-card-meta">${used.length ? `used by ${used.length}: ` + used.slice(0, 4).map((u) => esc(`${u.kind === 'page' ? (u.title || u.what) : u.what} (${u.branch})`)).join(', ') + (used.length > 4 ? '…' : '') : st.usages ? 'used nowhere yet' : 'reading who uses it…'}</div>
          <div class="mk-card-body"><iframe class="mk-preview" title="${esc(e.name)}" data-src="${esc(previewSrc(e.name, e.draft, versionOf(e)))}" style="height:${CARD_MIN}px"></iframe><div class="mk-shield"></div></div>
          <div class="kt-card-actions">
            ${working ? `<span class="kt-working"><span class="spin"></span> the AI rewrites it${working > 1 ? ` · ${working} in a row` : ''}</span>` : ''}
            ${pending ? `<button type="button" class="mini on" data-kt="apply" data-name="${esc(e.name)}" title="Apply the pending requests of this card to the fragment, in one AI call">apply ${pending} request${pending === 1 ? '' : 's'}</button>` : working ? '' : '<span class="muted">drop a request pin on the card, then apply it</span>'}
            ${e.draft && !working ? `<button type="button" class="mini on" data-kt="save" data-name="${esc(e.name)}">save…</button><button type="button" class="mini" data-kt="drop-draft" data-name="${esc(e.name)}">drop the draft</button>` : ''}
            <span class="spacer"></span>
            ${!used.length && st.usages && !working ? `<button type="button" class="mini" data-kt="delete" data-name="${esc(e.name)}" title="Used on no active branch: it may go">delete</button>` : ''}
          </div>
          <div class="kt-save" hidden><b>Save the draft</b><div class="kt-row"><button type="button" class="mini on" data-kt="save-replace" data-name="${esc(e.name)}" title="The draft takes the component's place: every page and micro-frontend that uses it shows the new one">replace ${esc(e.name)}${used.length ? ` (${used.length} usage${used.length === 1 ? '' : 's'})` : ''}</button><input class="kt-fork-name" maxlength="60" placeholder="${esc(e.name)}2" aria-label="fork name"><button type="button" class="mini" data-kt="save-fork" data-name="${esc(e.name)}" title="A new component from the draft; this one stays as it is">fork</button></div>${used.length ? `<div class="muted">Replacing changes: ${used.map((u) => esc(`${u.kind} ${u.what} on ${u.branch}`)).join('; ')}</div>` : ''}</div>
        </div>`;
    }
    function drawCards() {
      if (!st.board) return;
      const list = catalog().filter((e) => e.state === 'generated' || e.draft);
      const content = st.board.content;
      if (!list.length) {
        content.innerHTML = '<div class="mk-empty" data-pin="kit:none"><h2>No component yet</h2><p>The canvas shows the kit once it is generated: tick the components in the <b>catalogue</b> and generate them from the validated design system.</p></div>';
        st.cards = [];
        st.board.setSize(WIDTH, MIN_HEIGHT);
        st.board.fit();
        return;
      }
      const empty = content.querySelector('.mk-empty');
      if (empty) empty.remove();
      const have = new Map([...content.querySelectorAll('.kt-card')].map((c) => [c.dataset.card, c]));
      const make = (html) => { const t = document.createElement('template'); t.innerHTML = html.trim(); return t.content.firstElementChild; };
      let before = null;
      const cards = list.map((e) => {
        const fresh = make(cardHtml(e));
        let card = have.get(e.name);
        have.delete(e.name);
        if (card && card.dataset.version === fresh.dataset.version) {
          // The same preview: everything but the frame is redrawn, the frame stays loaded.
          const open = !card.querySelector('.kt-save').hidden;
          const fork = card.querySelector('.kt-fork-name').value;
          [...card.children].forEach((child) => { if (!child.classList.contains('mk-card-body')) child.remove(); });
          const body = card.querySelector('.mk-card-body');
          [...fresh.children].forEach((child) => { if (!child.classList.contains('mk-card-body')) card.insertBefore(child, child.classList.contains('kt-card-actions') || child.classList.contains('kt-save') ? null : body); });
          card.querySelector('.kt-save').hidden = !open;
          card.querySelector('.kt-fork-name').value = fork;
        } else {
          if (card) { const height = card.querySelector('.mk-preview') && card.querySelector('.mk-preview').style.height; card.replaceWith(fresh); if (height) fresh.querySelector('.mk-preview').style.height = height; } else content.insertBefore(fresh, before ? before.nextSibling : content.firstChild);
          card = fresh;
          const frame = card.querySelector('.mk-preview');
          if (frame) { frame.addEventListener('load', measureCards); watchFrame(frame); }
        }
        before = card;
        return { name: e.name, card, frame: card.querySelector('.mk-preview') };
      });
      have.forEach((card) => { const frame = card.querySelector('.mk-preview'); if (frame && st.seen) st.seen.unobserve(frame); card.remove(); });
      st.cards = cards;
      layoutCards();
      if (!st.fitted) { st.board.fit(); st.fitted = true; }
    }
    // A preview is a whole document, its scripts running: only the cards on
    // the screen, and a little around it, hold one. A card scrolled or
    // zoomed away lets its document go and keeps its height; it loads again
    // when it comes back.
    function watchFrame(frame) {
      if (!window.IntersectionObserver) { frame.src = frame.dataset.src; return; }
      if (!st.seen) {
        st.seen = new IntersectionObserver((entries) => {
          entries.forEach((entry) => {
            const f = entry.target;
            if (entry.isIntersecting) {
              if (f.dataset.loaded !== f.dataset.src) { f.dataset.loaded = f.dataset.src; f.src = f.dataset.src; }
            } else if (f.dataset.loaded) {
              delete f.dataset.loaded;
              f.src = 'about:blank';
            }
          });
        }, { root: q('.kt-board'), rootMargin: '300px' });
      }
      st.seen.observe(frame);
    }
    function measureCards() {
      let changed = false;
      st.cards.forEach((c) => {
        // A frame let go keeps the height it had: its card does not move.
        if (!c.frame || !c.frame.dataset.loaded) return;
        let doc = null;
        try { doc = c.frame.contentDocument; } catch (e) { doc = null; }
        if (!doc || !doc.body) return;
        const h = Math.min(CARD_MAX, Math.max(CARD_MIN, doc.documentElement.scrollHeight, doc.body.scrollHeight));
        if (Math.abs(h - (parseFloat(c.frame.style.height) || 0)) > 2) { c.frame.style.height = h + 'px'; changed = true; }
      });
      if (changed) layoutCards();
    }
    function layoutCards() {
      const per = Math.max(1, Math.floor((WIDTH + CARD_GAP) / (CARD_W + CARD_GAP)));
      let y = 0; let rowH = 0; let maxX = 0;
      st.cards.forEach((c, i) => {
        if (i % per === 0 && i) { y += rowH + CARD_GAP; rowH = 0; }
        const x = (i % per) * (CARD_W + CARD_GAP);
        c.card.style.left = x + 'px'; c.card.style.top = y + 'px';
        rowH = Math.max(rowH, c.card.offsetHeight);
        maxX = Math.max(maxX, x + CARD_W);
      });
      st.board.setSize(Math.max(WIDTH, maxX), Math.max(MIN_HEIGHT, y + rowH + 20));
      st.board.refresh();
    }
    async function loadUsages() {
      try {
        const res = await fetch('/api/kit/usages');
        st.usages = res.ok ? await res.json() : {};
      } catch (e) { st.usages = {}; }
      if (!st.gone && st.tab === 'canvas') drawCards();
    }
    // Applies requests to a component: its draft is rewritten, the pins
    // applied go (ctrl+z on the board brings one back), the skipped stay.
    async function applyRequests(name, notes) {
      if (!name || !st.board) return;
      const asked = notes.filter((n) => (n.text || '').trim()).map((n) => ({ id: n.id, text: n.text, target: '' }));
      if (!asked.length) { toast('nothing to apply: write the request first'); return; }
      const action = window.HarnessActions && window.HarnessActions.start({ key: `kit-apply:${name}:${asked.map((a) => a.id).join(',')}`, label: `apply ${asked.length} request(s) to ${name}` });
      // Several at once are fine: the server rewrites a component one request after the other.
      st.applying[name] = (st.applying[name] || 0) + 1;
      drawCards();
      try {
        const got = await said(await post(`/api/kit/${encodeURIComponent(name)}/apply`, { requests: asked }));
        const skipped = got.skipped || [];
        asked.forEach((a) => { if (!skipped.some(([id]) => id === a.id)) st.board.drop(a.id); });
        skipped.forEach(([id, why]) => toast(`request ${esc(id)}: ${esc(why)}`));
        if (action) action.ok(`${asked.length - skipped.length} applied`);
        st.rev[name] = (st.rev[name] || 0) + 1;
      } catch (e) {
        if (action) action.fail(e.message || e);
        toast(`${esc(name)}: not applied — ${esc(String(e.message || e).split('\n')[0])}`);
      } finally {
        st.applying[name] = Math.max(0, (st.applying[name] || 1) - 1);
        if (!st.gone) await load(false);
      }
    }

    // ---- what the human does ---------------------------------------------------------------------
    host.addEventListener('click', async (e) => {
      const b = e.target.closest('[data-kt]');
      if (!b || b.disabled) return;
      const what = b.dataset.kt; const name = b.dataset.name || '';
      const card = (n) => st.cards.find((c) => c.name === n);
      switch (what) {
        case 'tab': setTab(b.dataset.tab); break;
        case 'publish': act('publishing', () => call('/api/design/publish', { message: q('.kt-message').value }), (got) => toast(`published on <b>${SLUG}</b> · ${esc(String(got.commit || '').slice(0, 10))}`)); break;
        case 'discard': if (window.confirm('Drop the workspace of the design-system branch? What is not published goes.')) act('discarding', () => call('/api/design/discard')); break;
        case 'tokens-example': q('.kt-json').value = exampleTokens(); break;
        case 'inject': act('injecting the tokens', () => call('/api/design/tokens', { json: q('.kt-json').value, edit: false })); break;
        case 'generate': act('the AI draws the design system', () => call('/api/design/generate', { brief: q('.kt-brief').value }), () => toast('the tokens are drawn: look at the sheet, retouch, validate')); break;
        case 'validate': act('validating', () => call('/api/design/validate'), (got) => { if (got && got.design && got.design.issue) toast(`validated — a roadmap task installs it in the product: <a href="${esc(got.design.issue)}" target="_blank" rel="noopener">open ↗</a>`, 10000); else toast('validated: the kit may be generated now'); }); break;
        case 'drop-candidate': act('dropping the candidate', () => call('/api/design/candidate/drop')); break;
        case 'remove-asset': act('removing', () => call('/api/design/asset/remove', { kind: b.dataset.kind, name: b.dataset.name })); break;
        case 'generate-all': act('queuing the generation', () => call('/api/kit/generate', { names: [] }), (got) => toast(`${got.queued} component(s) queued`)); break;
        case 'generate-one': act(`queuing ${name}`, () => call('/api/kit/generate', { names: [name] })); break;
        case 'delete': if (window.confirm(`Remove ${name} from the kit?`)) act(`removing ${name}`, () => fetch(`/api/kit/${encodeURIComponent(name)}`, { method: 'DELETE' }).then(said), () => { st.usages = null; }); break;
        case 'edit-prompt': {
          const en = entry(name); if (!en) break;
          const prompt = window.prompt(`The prompt of ${name}:`, en.prompt || '');
          if (prompt != null) act(`keeping the prompt of ${name}`, () => call(`/api/kit/${encodeURIComponent(name)}/prompt`, { prompt, title: en.title }));
          break;
        }
        case 'reference': {
          const input = document.createElement('input'); input.type = 'file'; input.accept = 'image/*';
          input.onchange = () => { if (input.files[0]) act(`keeping the reference of ${name}`, () => upload('reference', input.files[0], name)); };
          input.click();
          break;
        }
        case 'sketch-toggle': { const pad = host.querySelector('.kt-sketch'); pad.hidden = !pad.hidden; if (!pad.hidden && !st.sketch) armSketch(pad.querySelector('canvas')); break; }
        case 'sketch-clear': if (st.sketch) st.sketch.clear(); break;
        case 'apply': {
          const pins = st.board.all().filter((n) => n.target === 'kit:' + name && n.kind === 'request' && (n.state || 'pending') !== 'simulated' && (n.text || '').trim() && !st.board.isApplying(n.id));
          st.board.track(pins.map((n) => n.id), applyRequests(name, pins));
          break;
        }
        case 'save': { const c = card(name); if (c) { const box = c.card.querySelector('.kt-save'); box.hidden = !box.hidden; layoutCards(); } break; }
        case 'save-replace': act(`replacing ${name}`, () => call(`/api/kit/${encodeURIComponent(name)}/save`, { how: 'replace' }), () => { toast(`${esc(name)} replaced: every page that uses it shows the new one`); st.usages = null; }); break;
        case 'save-fork': { const c = card(name); const forkName = c ? c.card.querySelector('.kt-fork-name').value.trim() : ''; act(`forking ${name}`, () => call(`/api/kit/${encodeURIComponent(name)}/save`, { how: 'fork', name: forkName }), (entries) => { const made = (entries || []).find((x) => x.variant_of === name && x.name !== name && (!forkName || x.name === forkName)); toast(`forked as <b>${esc(made ? made.name : forkName || name + '2')}</b>; ${esc(name)} is as it was`); st.usages = null; }); break; }
        case 'drop-draft': act(`dropping the draft of ${name}`, () => call(`/api/kit/${encodeURIComponent(name)}/draft/drop`)); break;
        default: break;
      }
    });
    host.addEventListener('change', async (e) => {
      const t = e.target;
      if (t.matches('[data-kt="tokens-file"]') && t.files[0]) { q('.kt-json').value = await t.files[0].text(); return; }
      if (t.matches('[data-kt="mood-files"]') && t.files.length) { const files = [...t.files]; act(`keeping ${files.length} image(s)`, async () => { for (const f of files) await upload('moodboard', f); }); return; }
      if (t.matches('[data-kt="logo-file"]') && t.files[0]) { act('keeping the logo', () => upload('logo', t.files[0])); return; }
      if (t.matches('.kt-check')) {
        const checked = [...host.querySelectorAll('.kt-check[data-base]')].filter((c) => c.checked).map((c) => c.dataset.base);
        act('ticking', () => call('/api/kit/checked', { checked }));
        return;
      }
      if (t.matches('input[type="color"][data-token]')) { const text = host.querySelector(`.kt-token[data-token="${CSS.escape(t.dataset.token)}"]`); if (text) { text.value = t.value; keepTokens(); } }
    });
    host.addEventListener('input', (e) => { if (e.target.matches('.kt-token')) keepTokens(); });
    function keepTokens() {
      clearTimeout(st.editTimer);
      st.editTimer = setTimeout(async () => {
        try {
          const got = await said(await post('/api/design/tokens', { json: tokensJsonEdited(), edit: true }));
          st.reply.design = got;
          const frame = host.querySelector('.kt-system .kt-sheet:not(.kt-candidate .kt-sheet)');
          if (frame) frame.srcdoc = sheet(got.tokens_css, got.tokens);
          const page = host.querySelector('.kt-showcase');
          if (page) page.src = page.src.replace(/\?.*$/, '') + '?v=' + Date.now();
          st.lastDrawn = '';
        } catch (err) { say(`<span class="bad">${esc(String(err.message || err).split('\n')[0])}</span>`); }
      }, 600);
    }
    host.addEventListener('submit', async (e) => {
      const form = e.target.closest('.kt-custom');
      if (!form) return;
      e.preventDefault();
      const name = form.name.value.trim(); const title = form.title.value.trim(); const prompt = form.prompt.value.trim();
      const file = form.reference.files[0];
      const state = form.querySelector('.kt-form-state');
      state.textContent = 'adding…';
      try {
        await said(await post('/api/kit/custom', { name, title, prompt }));
        if (file) await upload('reference', file, name);
        else if (st.sketch && st.sketch.drawn()) { const blob = await st.sketch.blob(); await upload('reference', new File([blob], 'sketch.png', { type: 'image/png' }), name); }
        state.textContent = '';
        st.sketch = null;
        toast(`<b>${esc(name)}</b> is in the kit, to generate`);
        await load(false);
      } catch (err) {
        state.textContent = String(err.message || err).split('\n')[0];
      }
    });
    function exampleTokens() {
      const d = design();
      if (d.tokens_json) return d.tokens_json;
      return JSON.stringify({ color: { primary: { $type: 'color', $value: '#2b6cb0' }, 'primary-contrast': { $type: 'color', $value: '#ffffff' }, secondary: { $type: 'color', $value: '#6b7280' }, accent: { $type: 'color', $value: '#d97706' }, surface: { $type: 'color', $value: '#ffffff' }, 'surface-2': { $type: 'color', $value: '#f3f4f6' }, text: { $type: 'color', $value: '#111827' }, 'text-muted': { $type: 'color', $value: '#6b7280' }, border: { $type: 'color', $value: '#d1d5db' }, danger: { $type: 'color', $value: '#b91c1c' }, success: { $type: 'color', $value: '#15803d' } }, font: { family: { $type: 'fontFamily', $value: 'system-ui, sans-serif' }, 'family-heading': { $type: 'fontFamily', $value: 'system-ui, sans-serif' }, 'size-small': { $type: 'dimension', $value: '12px' }, 'size-base': { $type: 'dimension', $value: '15px' }, 'size-large': { $type: 'dimension', $value: '20px' }, 'size-heading': { $type: 'dimension', $value: '28px' }, 'weight-heading': { $type: 'fontWeight', $value: '700' } }, space: { 1: { $type: 'dimension', $value: '4px' }, 2: { $type: 'dimension', $value: '8px' }, 3: { $type: 'dimension', $value: '16px' }, 4: { $type: 'dimension', $value: '24px' }, 5: { $type: 'dimension', $value: '40px' } }, radius: { small: { $type: 'dimension', $value: '4px' }, medium: { $type: 'dimension', $value: '8px' }, large: { $type: 'dimension', $value: '16px' }, pill: { $type: 'dimension', $value: '999px' } }, shadow: { low: { $type: 'shadow', $value: '0 1px 3px rgba(0, 0, 0, 0.12)' }, high: { $type: 'shadow', $value: '0 8px 24px rgba(0, 0, 0, 0.18)' } }, border: { width: { $type: 'dimension', $value: '1px' } } }, null, 2);
    }

    load(false);
    return {
      reload: () => load(false),
      // What a desk is told of the part under the pointer: a card of the canvas, or the tab shown.
      contextAt(clientX, clientY, el) {
        if (st.tab === 'canvas') {
          const part = el && el.closest ? el.closest('[data-pin]') : null;
          const target = part ? part.getAttribute('data-pin') || '' : '';
          return { what: describe(target), text: context(target) };
        }
        const d = design().design || {};
        return {
          what: `the ${st.tab} tab of the design system's easel`,
          text: `The design system: ${d.state || 'none'}${d.source ? ', ' + d.source : ''}; ${design().tokens.length} token(s) in mock/design/tokens.json, derived into mock/design/tokens.css, on the product's design-system branch. The kit: ${catalog().filter((e) => e.state === 'generated').length} component(s) generated, listed in mock/kit/kit.json.`,
        };
      },
      destroy() {
        st.gone = true;
        clearTimeout(st.timer); clearTimeout(st.editTimer); clearTimeout(st.toastTimer);
        if (st.seen) st.seen.disconnect();
        if (st.board) { try { st.board.destroy(); } catch (e) { /* gone */ } }
        host.innerHTML = '';
      },
    };
  }

  window.KitPane = { mount };
})();
